INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('33b44191-684d-5764-8d5c-3a52a357340c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 9, 9, 'An ultrasound probe emits waves of frequency 3.5 MHz into soft tissue, where they travel at 1540 m s⁻¹. Calculate the wavelength in mm.', NULL, 1, 'numeric'::answer_type, '0.44 mm', 'mm', false, NULL, false, NULL, 'λ = v/f = 1540 ÷ 3.5 × 10⁶ = 4.400 × 10⁻⁴ m. In mm: 4.400 × 10⁻⁴ × 10³ = 0.440. Mark scheme (2 marks). C1: λ = v/f. A1: λ = 0.440 mm.', 2, NULL, NULL),
('97f10a8c-2362-53fc-b254-1541c670cb69', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 10, 10, 'Which description of ultrasound is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Sound with a frequency above about 20 kHz, the upper limit of human hearing', NULL, false, NULL, false, NULL, 'Medical ultrasound typically uses 1–15 MHz. Mark scheme (1 mark). B1: C (Sound with a frequency above about 20 kHz, the upper limit of human hearing).', 1, NULL, NULL),
('bfaee7d7-b65b-5e73-a183-23b322e91b70', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 11, 11, 'Fat has a density of 920 kg m⁻³ and ultrasound travels through it at 1450 m s⁻¹. Calculate its specific acoustic impedance in units of 10⁶ kg m⁻² s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.334', '10⁶ kg m⁻² s⁻¹', false, NULL, false, NULL, 'Z = ρc = 920 × 1450 = 1.33 × 10⁶ kg m⁻² s⁻¹. Mark scheme (2 marks). C1: Z = ρc. A1: Z = 1.33 × 10⁶ kg m⁻² s⁻¹.', 2, NULL, NULL),
('8d8c2b06-eb24-56cd-8112-c4584b7afe3f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 12, 12, 'How does a piezoelectric crystal produce ultrasound?', NULL, 1, 'multiple_choice'::answer_type, 'An alternating p.d. makes the crystal vibrate at the same frequency', NULL, false, NULL, false, NULL, 'The crystal changes shape with the applied p.d. Mark scheme (1 mark). B1: A (An alternating p.d. makes the crystal vibrate at the same frequency).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 260" role="img" aria-labelledby="fg039b807b-t fg039b807b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg039b807b-t">Ultrasound transducer</title><desc id="fg039b807b-d">Cross-section of an ultrasound transducer showing the piezoelectric crystal, its electrodes and leads, the backing block and the matching layer.</desc><rect x="100" y="30" width="140" height="170" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="40" width="120" height="70" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="75" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">backing block</text><rect x="110" y="110" width="120" height="30" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">piezoelectric crystal</text><line x1="110" y1="110" x2="230" y2="110" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="230" y2="140" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="140" width="120" height="14" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="152" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">matching layer</text><line x1="130" y1="110" x2="130" y2="12" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="210" y1="140" x2="210" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136" y="16" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">leads to a.c. supply / receiver</text><line x1="130" y1="206" x2="130" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,246 127.5,240.6 132.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="170" y1="206" x2="170" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,246 167.5,240.6 172.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="210" y1="206" x2="210" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="210,246 207.5,240.6 212.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="250" y="230" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">ultrasound pulse</text></svg>', 'Cross-section of an ultrasound transducer showing the piezoelectric crystal, its electrodes and leads, the backing block and the matching layer.'),
('2ebdea4e-ee5d-52dd-90b3-a0b898e71807', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 13, 13, 'Ultrasound passes from muscle (Z = 1.70 × 10⁶ kg m⁻² s⁻¹) into bone (Z = 7.80 × 10⁶ kg m⁻² s⁻¹). Calculate the intensity reflection coefficient.', NULL, 1, 'numeric'::answer_type, '0.4123', NULL, false, NULL, false, NULL, 'α = (Z₂ − Z₁)² ÷ (Z₂ + Z₁)² = (7.80 − 1.70)² ÷ (7.80 + 1.70)² = 0.412. Mark scheme (2 marks). C1: reflection coefficient formula. A1: α = 0.412.', 2, NULL, NULL),
('a54a02ab-8e28-5910-afd8-726eab398317', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 14, 14, 'What property of two materials decides how much ultrasound is reflected at their boundary?', NULL, 1, 'multiple_choice'::answer_type, 'The difference between their acoustic impedances', NULL, false, NULL, false, NULL, 'Large impedance differences give strong reflections. Mark scheme (1 mark). B1: D (The difference between their acoustic impedances).', 1, NULL, NULL),
('a4c15828-78ea-5292-913f-73ad763b0091', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 15, 15, 'A transducer produces ultrasound with a wavelength of 0.50 mm in tissue where the speed is 1500 m s⁻¹. Calculate the frequency in MHz.', NULL, 1, 'numeric'::answer_type, '3 MHz', 'MHz', false, NULL, false, NULL, 'f = v/λ = 1500 ÷ 0.50 × 10⁻³ = 3.0 × 10⁶ Hz. In MHz: 3.0 × 10⁶ ÷ 10⁶ = 3.0. Mark scheme (2 marks). C1: f = v/λ. A1: f = 3.0 MHz.', 2, NULL, NULL),
('1a72c368-dac7-5be4-b039-63419439d6bf', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 16, 16, 'Why is a coupling gel put on the skin before an ultrasound scan?', NULL, 1, 'multiple_choice'::answer_type, 'It removes the air gap, which would reflect almost all the ultrasound', NULL, false, NULL, false, NULL, 'Air has a tiny acoustic impedance compared with skin. Mark scheme (1 mark). B1: B (It removes the air gap, which would reflect almost all the ultrasound).', 1, NULL, NULL),
('f606a8f6-82b1-505d-ab11-7c8ea460e317', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 17, 17, 'A reflection coefficient at a boundary is 0.0040. What fraction of the incident intensity is transmitted?', NULL, 1, 'numeric'::answer_type, '0.996', NULL, false, NULL, false, NULL, 'Transmitted = 1 − 0.0040 = 0.9960. Mark scheme (2 marks). C1: 1 − α. A1: fraction = 0.9960.', 2, NULL, NULL),
('9bbc0ee6-7bf9-538c-a725-7f8e209e6efa', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 18, 18, 'In which unit is specific acoustic impedance measured?', NULL, 1, 'multiple_choice'::answer_type, 'kg m⁻² s⁻¹', NULL, false, NULL, false, NULL, 'Z = ρc: kg m⁻³ × m s⁻¹. Mark scheme (1 mark). B1: C (kg m⁻² s⁻¹).', 1, NULL, NULL),
('922b08ad-e9d3-589d-887c-608849e6baa7', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 19, 19, 'Bone has an acoustic impedance of 7.8 × 10⁶ kg m⁻² s⁻¹ and a density of 1900 kg m⁻³. Calculate the speed of ultrasound in bone.', NULL, 1, 'numeric'::answer_type, '4105', 'm s⁻¹', false, NULL, false, NULL, 'c = Z/ρ = 7.8 × 10⁶ ÷ 1900 = 4110 m s⁻¹. Mark scheme (2 marks). C1: c = Z/ρ. A1: c = 4110 m s⁻¹.', 2, NULL, NULL),
('09627ca1-8c59-593c-ba25-dfaab4a5bea3', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 20, 20, 'How does a piezoelectric transducer detect returning ultrasound?', NULL, 1, 'multiple_choice'::answer_type, 'The echo makes the crystal vibrate, producing an alternating p.d. across it', NULL, false, NULL, false, NULL, 'The piezoelectric effect works both ways. Mark scheme (1 mark). B1: A (The echo makes the crystal vibrate, producing an alternating p.d. across it).', 1, NULL, NULL),
('081e94c2-f1b8-5751-a168-587a5e04847e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 21, 21, 'Ultrasound of frequency 5.0 MHz has a wavelength of 0.31 mm in muscle. Calculate the speed of ultrasound in muscle.', NULL, 1, 'numeric'::answer_type, '1550', 'm s⁻¹', false, NULL, false, NULL, 'v = fλ = 5.0 × 10⁶ × 0.31 × 10⁻³ = 1550 m s⁻¹. Mark scheme (2 marks). C1: v = fλ. A1: v = 1550 m s⁻¹.', 2, NULL, NULL),
('97bfb79c-7987-5ebc-a889-502c7204ddc4', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 22, 22, 'Why is ultrasound thought to be safer than X-rays for scanning a fetus?', NULL, 1, 'multiple_choice'::answer_type, 'It is not ionising radiation', NULL, false, NULL, false, NULL, 'At diagnostic intensities ultrasound does not ionise atoms. Mark scheme (1 mark). B1: D (It is not ionising radiation).', 1, NULL, NULL),
('070a7164-18b7-5aae-b4b2-6c9674660e78', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 23, 23, 'A water bath used for ultrasound tests has ρ = 1000 kg m⁻³, and sound crosses it at 1500 m s⁻¹. What is the specific acoustic impedance of the water, in units of 10⁶ kg m⁻² s⁻¹?', NULL, 1, 'numeric'::answer_type, '1.5', '10⁶ kg m⁻² s⁻¹', false, NULL, false, NULL, 'Z = ρc = 1000 × 1500 = 1.5 × 10⁶ kg m⁻² s⁻¹. Mark scheme (2 marks). C1: Z = ρc. A1: Z = 1.5 × 10⁶ kg m⁻² s⁻¹.', 2, NULL, NULL),
('21665eee-b454-5c79-b1c8-289a693f30c6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 24, 24, 'At a boundary between two materials of equal acoustic impedance, how much ultrasound is reflected?', NULL, 1, 'multiple_choice'::answer_type, 'None', NULL, false, NULL, false, NULL, 'α = (Z₂ − Z₁)²/(Z₂ + Z₁)² = 0 when Z₁ = Z₂. Mark scheme (1 mark). B1: B (None).', 1, NULL, NULL),
('23e493a0-da83-52de-9aa9-d50cee90ddac', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 25, 25, 'Ultrasound of frequency 2.5 MHz travels at 1500 m s⁻¹. Calculate its wavelength in mm.', NULL, 1, 'numeric'::answer_type, '0.6 mm', 'mm', false, NULL, false, NULL, 'λ = 1500 ÷ 2.5 × 10⁶ = 6.0 × 10⁻⁴ m. In mm: 6.0 × 10⁻⁴ × 10³ = 0.60. Mark scheme (1 mark). A1: λ = 0.60 mm.', 1, NULL, NULL),
('c927a45c-9e0b-5f6d-8369-f0c4b7205860', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 26, 26, 'Ultrasound of frequency 8.0 MHz is used to image an eye, where it travels at 1530 m s⁻¹. Calculate the wavelength in mm.', NULL, 1, 'numeric'::answer_type, '0.1912 mm', 'mm', false, NULL, false, NULL, 'λ = v/f = 1530 ÷ 8.0 × 10⁶ = 1.912 × 10⁻⁴ m. In mm: 1.912 × 10⁻⁴ × 10³ = 0.191. Mark scheme (2 marks). C1: λ = v/f. A1: λ = 0.191 mm.', 2, NULL, NULL),
('7c878094-54a4-5aa1-87ce-e02b7f4897c4', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 27, 27, 'At one boundary the intensity reflection coefficient is 0.43. What percentage of the incident intensity passes on through the boundary?', NULL, 1, 'numeric'::answer_type, '57', '%', false, NULL, false, NULL, 'Transmitted = (1 − 0.43) × 100 = 57 %. Mark scheme (2 marks). C1: 1 − α. A1: percentage = 57%.', 2, NULL, NULL),
('e5a5c615-ff92-5034-9a2a-f8f6c1879701', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 28, 28, 'Ultrasound meets a boundary between soft tissue (Z = 1.63 × 10⁶ kg m⁻² s⁻¹) and fat (Z = 1.33 × 10⁶ kg m⁻² s⁻¹). Calculate the percentage of the intensity reflected.', NULL, 2, 'numeric'::answer_type, '1.027', '%', false, NULL, false, NULL, 'α = (1.33 − 1.63)² ÷ (1.33 + 1.63)² = 0.01027. Percentage = 0.01027 × 100 = 1.03 %. Mark scheme (3 marks). C1: formula. C1: × 100. A1: percentage = 1.03%.', 3, NULL, NULL),
('6333a32b-619d-50ef-a9f6-554bf6c8039e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 29, 29, 'Ultrasound passes from air (Z = 430 kg m⁻² s⁻¹) into skin (Z = 1.7 × 10⁶ kg m⁻² s⁻¹). Calculate the fraction of the intensity transmitted into the skin.', NULL, 2, 'numeric'::answer_type, '0.001011', NULL, false, NULL, false, NULL, 'α = (1.7 × 10⁶ − 430)² ÷ (1.7 × 10⁶ + 430)² = 0.998989. Transmitted = 1 − 0.998989 = 0.00101. Mark scheme (4 marks). C1: reflection coefficient. C1: very close to 1. C1: transmitted = 1 − α. A1: fraction = 0.00101.', 4, NULL, NULL),
('5c405303-93aa-56f9-ad04-c7e31fb96404', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 30, 30, 'Why is a gel chosen whose acoustic impedance is close to that of skin?', NULL, 2, 'multiple_choice'::answer_type, 'So that very little ultrasound is reflected at the probe–skin boundary', NULL, false, NULL, false, NULL, 'Matched impedances give nearly complete transmission. Mark scheme (3 marks). C1: impedance matching. C1: little reflection. A1: C (So that very little ultrasound is reflected at the probe–skin boundary).', 3, NULL, NULL),
('f6b28214-b3d7-53d3-9e7d-1a343a7498d1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 31, 31, 'Soft tissue has an acoustic impedance of 1.63 × 10⁶ kg m⁻² s⁻¹ and the speed of ultrasound in it is 1540 m s⁻¹. Calculate its density.', NULL, 2, 'numeric'::answer_type, '1058', 'kg m⁻³', false, NULL, false, NULL, 'ρ = Z/c = 1.63 × 10⁶ ÷ 1540 = 1060 kg m⁻³. Mark scheme (3 marks). C1: Z = ρc. C1: rearranged. A1: ρ = 1060 kg m⁻³.', 3, NULL, NULL),
('755c4551-cc5b-5af8-9711-86a85a91ea1c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 32, 32, 'At a boundary 32% of the incident ultrasound intensity is reflected. The incident intensity is 50 mW cm⁻². Calculate the transmitted intensity in mW cm⁻².', NULL, 2, 'numeric'::answer_type, '34', 'mW cm⁻²', false, NULL, false, NULL, 'Transmitted = (1 − 0.32) × 50 = 34 mW cm⁻². Mark scheme (3 marks). C1: 1 − α. C1: × incident. A1: I = 34 mW cm⁻².', 3, NULL, NULL),
('d9d36cbd-ac4b-57f4-82ae-d64e21676e2a', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 33, 33, 'Why does a higher ultrasound frequency give finer detail in an image?', NULL, 2, 'multiple_choice'::answer_type, 'The wavelength is shorter, so smaller structures can be resolved', NULL, false, NULL, false, NULL, 'Resolution is limited to roughly one wavelength. Mark scheme (3 marks). C1: λ = v/f smaller. C1: finer resolution. A1: A (The wavelength is shorter, so smaller structures can be resolved).', 3, NULL, NULL),
('9f4152d2-a4f1-576a-a469-d311e497e2a2', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 34, 34, 'Ultrasound in tissue is attenuated with an attenuation coefficient of 46 m⁻¹. What fraction of the intensity remains after travelling 30 mm?', NULL, 2, 'numeric'::answer_type, '0.2516', NULL, false, NULL, false, NULL, 'I/I₀ = e^(−46 × 0.030) = 0.252. Mark scheme (3 marks). C1: I = I₀e^(−kx). C1: mm to m. A1: fraction = 0.252.', 3, NULL, NULL),
('c4d8c090-d175-5a46-bd68-d51e7e15c510', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 35, 35, 'Ultrasound travels 40 mm to a boundary and 40 mm back through tissue with attenuation coefficient 50 m⁻¹. At the boundary 1.0% of the intensity is reflected. What fraction of the original intensity returns to the probe?', NULL, 2, 'numeric'::answer_type, '1.832e-4', NULL, false, NULL, false, NULL, 'Fraction = 0.010 × e^(−50 × 0.080) = 1.83 × 10⁻⁴. Mark scheme (4 marks). M1: total path 80 mm. C1: attenuation factor. C1: × reflection. A1: fraction = 1.83 × 10⁻⁴.', 4, NULL, NULL),
('0de5afe3-e073-586d-9055-b091751bf165', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 36, 36, 'Why is ultrasound almost completely reflected at a tissue–bone boundary?', NULL, 2, 'multiple_choice'::answer_type, 'Bone has a much larger acoustic impedance than soft tissue', NULL, false, NULL, false, NULL, 'The large difference in Z gives a large α. Mark scheme (3 marks). C1: large ΔZ. C1: large reflection. A1: D (Bone has a much larger acoustic impedance than soft tissue).', 3, NULL, NULL),
('abd5d90a-a8c1-5c37-9aef-fc6f66a11d44', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 37, 37, 'Muscle has a density of 1075 kg m⁻³ and an acoustic impedance of 1.71 × 10⁶ kg m⁻² s⁻¹. Calculate the wavelength of 4.0 MHz ultrasound in muscle, in mm.', NULL, 2, 'numeric'::answer_type, '0.3977 mm', 'mm', false, NULL, false, NULL, 'c = Z/ρ = 1.71 × 10⁶ ÷ 1075 = 1591 m s⁻¹. λ = 1591 ÷ 4.0 × 10⁶ = 3.977 × 10⁻⁴ m. In mm: 3.977 × 10⁻⁴ × 10³ = 0.398. Mark scheme (3 marks). C1: c = Z/ρ. C1: λ = c/f. C1: m to mm.', 3, NULL, NULL),
('70c98871-9f00-5fe6-b74e-355eec98b342', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 38, 38, 'A probe emits pulses of 4 complete cycles at 2.0 MHz. Calculate the duration of each pulse in µs.', NULL, 2, 'numeric'::answer_type, '2 us', 'µs', false, NULL, false, NULL, 'T = 1 ÷ 2.0 × 10⁶ = 5.0 × 10⁻⁷ s. Pulse = 4 × 5.0 × 10⁻⁷ = 2.0 × 10⁻⁶ s, which in µs is 2.0 × 10⁻⁶ × 10⁶ = 2.0. Mark scheme (3 marks). C1: period. C1: × 4. A1: duration = 2.0 µs.', 3, NULL, NULL),
('e966a07a-d2c0-54e3-9319-6a0c798c91b6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 39, 39, 'Why is a lower frequency used to image organs deep in the body?', NULL, 2, 'multiple_choice'::answer_type, 'Lower-frequency ultrasound is attenuated less, so it penetrates further', NULL, false, NULL, false, NULL, 'Attenuation rises with frequency, so depth and resolution trade off. Mark scheme (3 marks). C1: less attenuation. C1: trade-off with resolution. A1: B (Lower-frequency ultrasound is attenuated less, so it penetrates further).', 3, NULL, NULL),
('68622565-633d-57d4-a60b-2252f94b8f06', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 40, 40, 'Calculate the intensity reflection coefficient at a boundary between blood (Z = 1.59 × 10⁶ kg m⁻² s⁻¹) and muscle (Z = 1.71 × 10⁶ kg m⁻² s⁻¹).', NULL, 2, 'numeric'::answer_type, '0.001322', NULL, false, NULL, false, NULL, 'α = (1.71 − 1.59)² ÷ (1.71 + 1.59)² = 0.00132. Mark scheme (3 marks). C1: formula. C1: substitution. A1: α = 0.00132.', 3, NULL, NULL),
('f8d56b8b-4d86-5a1c-95a2-2c50615a79cd', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 41, 41, 'What is the purpose of the backing block behind the piezoelectric crystal in a transducer?', NULL, 2, 'multiple_choice'::answer_type, 'To damp the vibrations quickly so that short pulses are produced', NULL, false, NULL, false, NULL, 'Short pulses give good resolution along the beam. Mark scheme (4 marks). C1: damping. C1: short pulses. C1: better depth resolution. A1: C (To damp the vibrations quickly so that short pulses are produced).', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 260" role="img" aria-labelledby="fg9d8b1c7e-t fg9d8b1c7e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9d8b1c7e-t">Ultrasound transducer</title><desc id="fg9d8b1c7e-d">Cross-section of an ultrasound transducer: a piezoelectric crystal between electrodes, a backing block behind it, a matching layer in front, and the pulse leaving the face.</desc><rect x="100" y="30" width="140" height="170" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="40" width="120" height="70" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="75" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">backing block</text><rect x="110" y="110" width="120" height="30" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">piezoelectric crystal</text><line x1="110" y1="110" x2="230" y2="110" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="230" y2="140" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="140" width="120" height="14" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="152" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">matching layer</text><line x1="130" y1="110" x2="130" y2="12" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="210" y1="140" x2="210" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136" y="16" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">leads to a.c. supply / receiver</text><line x1="130" y1="206" x2="130" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,246 127.5,240.6 132.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="170" y1="206" x2="170" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,246 167.5,240.6 172.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="210" y1="206" x2="210" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="210,246 207.5,240.6 212.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="250" y="230" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">ultrasound pulse</text></svg>', 'Cross-section of an ultrasound transducer: a piezoelectric crystal between electrodes, a backing block behind it, a matching layer in front, and the pulse leaving the face.'),
('f240bdf8-e7b0-5d0e-9733-1524646c5700', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 42, 42, 'A crystal resonates when its thickness is half a wavelength. Ultrasound travels at 4000 m s⁻¹ in the crystal. What thickness gives a 2.0 MHz resonance, in mm?', NULL, 2, 'numeric'::answer_type, '1 mm', 'mm', false, NULL, false, NULL, 'λ = 4000 ÷ 2.0 × 10⁶ = 2.0 × 10⁻³ m. Thickness = 2.0 × 10⁻³ ÷ 2 = 1.0 × 10⁻³ m, which in mm is 1.0 × 10⁻³ × 10³ = 1.0. Mark scheme (3 marks). C1: λ in crystal. C1: half of it. A1: t = 1.0 mm.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 260" role="img" aria-labelledby="fg182f04cc-t fg182f04cc-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg182f04cc-t">Transducer crystal</title><desc id="fg182f04cc-d">Cross-section of an ultrasound transducer; the thickness of the piezoelectric crystal sets its resonant frequency.</desc><rect x="100" y="30" width="140" height="170" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="40" width="120" height="70" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="75" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">backing block</text><rect x="110" y="110" width="120" height="30" rx="0" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">piezoelectric crystal</text><line x1="110" y1="110" x2="230" y2="110" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="230" y2="140" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="140" width="120" height="14" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="152" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">matching layer</text><line x1="130" y1="110" x2="130" y2="12" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="210" y1="140" x2="210" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136" y="16" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">leads to a.c. supply / receiver</text><line x1="130" y1="206" x2="130" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,246 127.5,240.6 132.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="170" y1="206" x2="170" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,246 167.5,240.6 172.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="210" y1="206" x2="210" y2="241.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="210,246 207.5,240.6 212.5,240.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="250" y="230" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">ultrasound pulse</text></svg>', 'Cross-section of an ultrasound transducer; the thickness of the piezoelectric crystal sets its resonant frequency.'),
('b5d774f2-5d84-5088-9d14-8c9261927401', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 43, 43, 'A probe sends ultrasound through gel (Z = 1.50 × 10⁶ kg m⁻² s⁻¹) into skin (Z = 1.70 × 10⁶ kg m⁻² s⁻¹). (a) Calculate the reflection coefficient at the gel–skin boundary. (b) Without gel, air (Z = 430 kg m⁻² s⁻¹) would be between them. Calculate the reflection coefficient at an air–skin boundary. (c) Calculate (fraction transmitted with gel) ÷ (fraction transmitted with air). Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '985', NULL, false, NULL, false, NULL, '(a) ((1.70 − 1.50) ÷ (1.70 + 1.50))² = 0.003906. (b) ((1.7 × 10⁶ − 430) ÷ (1.7 × 10⁶ + 430))² = 0.998989. (c) (1 − 0.003906) ÷ (1 − 0.998989) = 985. Mark scheme (5 marks). C1: gel α. C1: air α. M1: transmitted fractions. C1: value. A1: ratio = 985.', 5, NULL, NULL),
('8e408cc7-8684-5ccb-b8d1-cbdccbd2b418', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 44, 44, 'Ultrasound of intensity 2.0 W m⁻² travels 50 mm through tissue (attenuation coefficient 40 m⁻¹) to a tissue–bone boundary that reflects 43% of the intensity. The echo returns along the same path. (a) Calculate the intensity reaching the boundary. (b) Calculate the reflected intensity. (c) Calculate the intensity of the echo arriving back at the probe. Give only the answer to (c), in units of 10⁻² W m⁻².', NULL, 3, 'numeric'::answer_type, '1.575', '10⁻² W m⁻²', false, NULL, false, NULL, '(a) 2.0 × e^(−40 × 0.050) = 0.2707 W m⁻². (b) 0.43 × 0.2707 = 0.1164 W m⁻². (c) 0.1164 × e^(−40 × 0.050) = 0.0158 W m⁻². Mark scheme (6 marks). C1: outward attenuation. C1: reflection. C1: return attenuation. M1: multiply factors. C1: value. A1: I = 1.58 × 10⁻² W m⁻².', 6, NULL, NULL),
('6f9e32cd-3a2e-5ea0-abf6-a36ec7d5831d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 45, 45, 'Bone has a density of 1900 kg m⁻³ and ultrasound travels in it at 4100 m s⁻¹; soft tissue has Z = 1.63 × 10⁶ kg m⁻² s⁻¹. (a) Calculate the acoustic impedance of bone. (b) Calculate the percentage of intensity reflected at a tissue–bone boundary.', NULL, 3, 'numeric'::answer_type, '42.76', '%', false, NULL, false, NULL, '(a) Z = 1900 × 4100 = 7.79 × 10⁶ kg m⁻² s⁻¹. (b) ((7.79 × 10⁶ − 1.63 × 10⁶) ÷ (7.79 × 10⁶ + 1.63 × 10⁶))² × 100 = 42.8 %. Mark scheme (5 marks). C1: Z = ρc. M1: α formula. C1: substitution. C1: value. A1: percentage = 42.8%.', 5, NULL, NULL),
('b010ddc0-a9cb-5393-96c0-86eede4d0ea1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 46, 46, 'A 5.0 MHz probe is used on tissue in which ultrasound travels at 1540 m s⁻¹ and the attenuation coefficient is 0.50 dB cm⁻¹ per MHz. (a) Calculate the wavelength in mm. (b) Calculate the total attenuation, in dB, for a round trip to a depth of 6.0 cm. (c) Explain why a lower frequency might be chosen. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '30', 'dB', false, NULL, false, NULL, '(a) λ = 1540 ÷ 5.0 × 10⁶ = 3.080 × 10⁻⁴ m, which is 0.308 mm. (b) Attenuation = 0.50 × 5.0 × 12.0 = 30 dB. (c) Lower frequency is attenuated less, giving a stronger echo from deep tissue, at the cost of resolution. Mark scheme (6 marks). C1: λ. M1: dB per cm at 5.0 MHz. C1: round trip 12 cm. C1: value. B1: trade-off. A1: attenuation = 30 dB.', 6, NULL, NULL),
('2504619f-8bd3-5cbb-9861-071ca1e9bfbf', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 47, 47, 'Ultrasound crosses fat (Z = 1.38 × 10⁶ kg m⁻² s⁻¹) into muscle (Z = 1.70 × 10⁶ kg m⁻² s⁻¹). (a) Calculate the reflection coefficient. (b) Calculate the fraction of the incident intensity that is transmitted into the muscle and then, after reflecting completely from a deeper bone, transmitted back into the fat. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.9785', NULL, false, NULL, false, NULL, '(a) α = ((1.70 − 1.38) ÷ (1.70 + 1.38))² = 0.01079. (b) The boundary is crossed twice: (1 − 0.01079)² = 0.979. Mark scheme (5 marks). C1: α. M1: transmission twice. C1: substitution. C1: value. A1: fraction = 0.979.', 5, NULL, NULL),
('4455e3ca-5930-513c-bcf5-83f6e94b2299', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 48, 48, 'An A-scan probe uses a 2.0 MHz pulse lasting 3 cycles in tissue where v = 1540 m s⁻¹. (a) Calculate the pulse duration. (b) Calculate the length of the pulse in the tissue, in mm. (c) Explain why two boundaries closer than about half this length cannot be separated. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.31 mm', 'mm', false, NULL, false, NULL, '(a) t = 3 ÷ 2.0 × 10⁶ = 1.5 × 10⁻⁶ s. (b) L = 1540 × 1.5 × 10⁻⁶ = 0.002310 m. In mm: 0.002310 × 10³ = 2.31. (c) Their echoes overlap in time. Mark scheme (6 marks). C1: duration. M1: length = vt. C1: m to mm. C1: value. B1: overlapping echoes. A1: L = 2.31 mm.', 6, NULL, NULL),
('00fb1bdd-d2a5-57db-9e69-c397a5fb96f8', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 49, 49, 'The intensity of an ultrasound beam falls to 25% of its initial value after passing through 4.0 cm of tissue. (a) Calculate the attenuation coefficient in cm⁻¹. (b) Calculate the distance over which the intensity halves, in cm.', NULL, 3, 'numeric'::answer_type, '2 cm', 'cm', false, NULL, false, NULL, '(a) 0.25 = e^(−4.0k), so k = ln 4 ÷ 4.0 = 0.3466 cm⁻¹. (b) Halving distance = ln 2 ÷ 0.3466 = 2.0 cm. Mark scheme (5 marks). M1: exponential equation. C1: k. M1: ln 2/k. C1: value. A1: x½ = 2.0 cm.', 5, NULL, NULL),
('a60cf0f2-a04f-52e4-9831-eb63eed56f45', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'c42a4d3d-be78-5670-938b-975bb2eaf1ec', 'a-level', '30.5', '9702 coursebook 30.5 · Ultrasound', 50, 50, 'An ultrasound beam passes from soft tissue (Z = 1.63 × 10⁶ kg m⁻² s⁻¹) into a kidney (Z = 1.65 × 10⁶ kg m⁻² s⁻¹). (a) Calculate the reflection coefficient. (b) Explain why such a weak echo can still be detected. (c) Calculate the reflected intensity if the incident intensity is 0.50 W m⁻², in units of 10⁻⁵ W m⁻². Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.859', '10⁻⁵ W m⁻²', false, NULL, false, NULL, '(a) α = ((1.65 − 1.63) ÷ (1.65 + 1.63))² = 3.718 × 10⁻⁵. (b) The receiver is very sensitive and the echoes are amplified electronically. (c) 0.50 × 3.718 × 10⁻⁵ = 1.86 × 10⁻⁵ W m⁻². Mark scheme (6 marks). C1: α. B1: sensitive detection / amplification. M1: I = α I₀. C1: substitution. C1: value. A1: I = 1.86 × 10⁻⁵ W m⁻².', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('fd1f2f7b-dccf-5605-8dbd-a1d8cb38171a', '97f10a8c-2362-53fc-b254-1541c670cb69', 'Electromagnetic waves above 20 kHz', 'A', false, 0),
('78870f43-389a-5723-8566-4937e0ca4e5a', '97f10a8c-2362-53fc-b254-1541c670cb69', 'Sound below 20 Hz', 'B', false, 1),
('ae2ed6bd-30a2-5771-8b27-023318ef0549', '97f10a8c-2362-53fc-b254-1541c670cb69', 'Sound with a frequency above about 20 kHz, the upper limit of human hearing', 'C', true, 2),
('8b84c5f4-0c8f-5ffc-a752-60bf02efe3de', '97f10a8c-2362-53fc-b254-1541c670cb69', 'Very loud audible sound', 'D', false, 3),
('eedaee89-e90b-5027-add0-3f3db9be79be', '8d8c2b06-eb24-56cd-8112-c4584b7afe3f', 'An alternating p.d. makes the crystal vibrate at the same frequency', 'A', true, 0),
('0a72d8c7-383c-5634-8873-df30edaefe5b', '8d8c2b06-eb24-56cd-8112-c4584b7afe3f', 'Heating the crystal makes it emit sound', 'B', false, 1),
('ddec8b55-44cf-5ee4-ab07-be6ab57e19ff', '8d8c2b06-eb24-56cd-8112-c4584b7afe3f', 'Light falling on it makes it vibrate', 'C', false, 2),
('f16b12cc-31bb-5fe1-9346-b77d865c0bcb', '8d8c2b06-eb24-56cd-8112-c4584b7afe3f', 'A steady p.d. makes it spin', 'D', false, 3),
('e91ba58b-1926-55ff-b0ec-6a878f0302df', 'a54a02ab-8e28-5910-afd8-726eab398317', 'The difference between their temperatures', 'A', false, 0),
('b7dcb7bd-ef51-5b81-a704-3ad32680c979', 'a54a02ab-8e28-5910-afd8-726eab398317', 'Their colours', 'B', false, 1),
('aff1752c-af60-564b-aba5-028b7096d1d4', 'a54a02ab-8e28-5910-afd8-726eab398317', 'Their electrical resistances', 'C', false, 2),
('2e4e2c33-98b8-52ff-98ff-013202543382', 'a54a02ab-8e28-5910-afd8-726eab398317', 'The difference between their acoustic impedances', 'D', true, 3),
('17d99f2c-53bc-595b-a74b-9503bae5e390', '1a72c368-dac7-5be4-b039-63419439d6bf', 'It cools the skin', 'A', false, 0),
('2af625cf-deb4-5aa5-a17b-166ae31f3670', '1a72c368-dac7-5be4-b039-63419439d6bf', 'It removes the air gap, which would reflect almost all the ultrasound', 'B', true, 1),
('809b3f19-999c-5f82-a638-44b5501ddcb2', '1a72c368-dac7-5be4-b039-63419439d6bf', 'It increases the frequency', 'C', false, 2),
('c33e92fc-6063-5d99-8d3f-80dbbe8e462a', '1a72c368-dac7-5be4-b039-63419439d6bf', 'It absorbs the ultrasound', 'D', false, 3),
('2ec4a6bf-cb28-5e31-8b06-d9f9dc37bc53', '9bbc0ee6-7bf9-538c-a725-7f8e209e6efa', 'kg m⁻³', 'A', false, 0),
('03377b4b-3a41-5a5e-9294-1a48f8b71cb3', '9bbc0ee6-7bf9-538c-a725-7f8e209e6efa', 'm s⁻¹', 'B', false, 1),
('6250b366-f0c3-59e1-89d3-66caccff64c1', '9bbc0ee6-7bf9-538c-a725-7f8e209e6efa', 'kg m⁻² s⁻¹', 'C', true, 2),
('24070759-205a-576b-ad6f-42f36ca0cc8b', '9bbc0ee6-7bf9-538c-a725-7f8e209e6efa', 'Pa', 'D', false, 3),
('09afb7a9-2eb9-5956-8854-53fc83ef4484', '09627ca1-8c59-593c-ba25-dfaab4a5bea3', 'The echo makes the crystal vibrate, producing an alternating p.d. across it', 'A', true, 0),
('4c2de49c-80e4-5b4a-8f77-c41b894cd917', '09627ca1-8c59-593c-ba25-dfaab4a5bea3', 'The echo heats the crystal', 'B', false, 1),
('d15351ff-db63-56f7-8a60-f52c01c74f07', '09627ca1-8c59-593c-ba25-dfaab4a5bea3', 'The echo changes its colour', 'C', false, 2),
('0ef9c3e5-c298-5153-9eee-aaeabba8314d', '09627ca1-8c59-593c-ba25-dfaab4a5bea3', 'The echo makes it emit light', 'D', false, 3),
('8c831533-114f-5596-a8e0-c6d25184c554', '97bfb79c-7987-5ebc-a889-502c7204ddc4', 'It travels faster than X-rays', 'A', false, 0),
('a12654e1-6c62-5a12-9dc2-b99a03348bda', '97bfb79c-7987-5ebc-a889-502c7204ddc4', 'It has a shorter wavelength', 'B', false, 1),
('805c2ef5-4edd-5232-aacb-6054819695a6', '97bfb79c-7987-5ebc-a889-502c7204ddc4', 'It cannot be absorbed by tissue', 'C', false, 2),
('537e1212-1bb1-563e-87cf-8f1cdd0e5a5f', '97bfb79c-7987-5ebc-a889-502c7204ddc4', 'It is not ionising radiation', 'D', true, 3),
('92eae4ec-9ee4-5b97-b91f-818ba0e1875d', '21665eee-b454-5c79-b1c8-289a693f30c6', 'All of it', 'A', false, 0),
('93b31c27-f8e3-57fc-b9e7-05ec6372e4d1', '21665eee-b454-5c79-b1c8-289a693f30c6', 'None', 'B', true, 1),
('9fe2f168-7d27-57b1-a130-b926f5948161', '21665eee-b454-5c79-b1c8-289a693f30c6', 'Half of it', 'C', false, 2),
('f4ece972-ce68-5bdd-88d8-2690b5663af4', '21665eee-b454-5c79-b1c8-289a693f30c6', 'It depends only on the frequency', 'D', false, 3),
('2dc62b77-159e-5777-94fd-1b87f1137afa', '5c405303-93aa-56f9-ad04-c7e31fb96404', 'So that the gel absorbs the ultrasound', 'A', false, 0),
('b83186f3-aa79-57d6-8848-af48004664ea', '5c405303-93aa-56f9-ad04-c7e31fb96404', 'So that the frequency increases', 'B', false, 1),
('406eaa0e-c661-5bf9-84f8-8990a7e35c45', '5c405303-93aa-56f9-ad04-c7e31fb96404', 'So that very little ultrasound is reflected at the probe–skin boundary', 'C', true, 2),
('fc9e75be-9041-559a-aaed-e97bc8e129f8', '5c405303-93aa-56f9-ad04-c7e31fb96404', 'So that the skin is not heated', 'D', false, 3),
('6e0142bf-9c11-504a-85e3-e4c3cdaa4773', 'd9d36cbd-ac4b-57f4-82ae-d64e21676e2a', 'The wavelength is shorter, so smaller structures can be resolved', 'A', true, 0),
('6e8adcf2-70dd-5d06-bf43-be18530c2bee', 'd9d36cbd-ac4b-57f4-82ae-d64e21676e2a', 'It travels faster', 'B', false, 1),
('71c873ae-3b6d-5765-af3b-c6cfb9f6b25d', 'd9d36cbd-ac4b-57f4-82ae-d64e21676e2a', 'It penetrates further', 'C', false, 2),
('b8a1edd6-ea96-58c0-92cd-579789a84e5d', 'd9d36cbd-ac4b-57f4-82ae-d64e21676e2a', 'It is reflected more strongly at every boundary', 'D', false, 3),
('3fa29bf2-2735-5b75-b2b8-703860b2ede7', '0de5afe3-e073-586d-9055-b091751bf165', 'Bone absorbs all ultrasound', 'A', false, 0),
('b8a66a1a-4a84-5565-87ac-7e5dc3ed9394', '0de5afe3-e073-586d-9055-b091751bf165', 'Bone has a lower density than tissue', 'B', false, 1),
('5d39cbf9-f79e-5c5c-8d6e-59248a23767e', '0de5afe3-e073-586d-9055-b091751bf165', 'Ultrasound cannot travel in solids', 'C', false, 2),
('6cb653e9-2b87-5dbc-b601-5f3a112d62c7', '0de5afe3-e073-586d-9055-b091751bf165', 'Bone has a much larger acoustic impedance than soft tissue', 'D', true, 3),
('ac3aeb99-457b-5363-9d50-f713a01278ce', 'e966a07a-d2c0-54e3-9319-6a0c798c91b6', 'It gives better resolution', 'A', false, 0),
('9c898345-e977-5f3d-8de2-e6e8460c3526', 'e966a07a-d2c0-54e3-9319-6a0c798c91b6', 'Lower-frequency ultrasound is attenuated less, so it penetrates further', 'B', true, 1),
('9ec3096a-66c7-57d0-9c93-c010e7c6b3bd', 'e966a07a-d2c0-54e3-9319-6a0c798c91b6', 'It is reflected more strongly', 'C', false, 2),
('29d945a6-f751-5129-a311-b717ed69c159', 'e966a07a-d2c0-54e3-9319-6a0c798c91b6', 'It travels faster', 'D', false, 3),
('ef9d3f86-526d-54da-b164-b6477b6d8619', 'f8d56b8b-4d86-5a1c-95a2-2c50615a79cd', 'To make the crystal vibrate for longer', 'A', false, 0),
('d7159b4a-7723-54d9-b1df-d7cba9f39dbe', 'f8d56b8b-4d86-5a1c-95a2-2c50615a79cd', 'To focus the beam', 'B', false, 1),
('9f60a046-a5ab-580d-89dc-4518131678f3', 'f8d56b8b-4d86-5a1c-95a2-2c50615a79cd', 'To damp the vibrations quickly so that short pulses are produced', 'C', true, 2),
('694c2561-99ae-581e-9f3f-e4983150148b', 'f8d56b8b-4d86-5a1c-95a2-2c50615a79cd', 'To cool the crystal', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('bb43798c-d403-5f6d-a655-6d3792cd10fd', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 7, 7, 'An echo from a boundary in tissue returns 80 µs after the pulse is sent. The speed of ultrasound in tissue is 1540 m s⁻¹. Calculate the depth of the boundary in mm.', NULL, 1, 'numeric'::answer_type, '61.6 mm', 'mm', false, NULL, false, NULL, 'd = vt/2 = 1540 × 80 × 10⁻⁶ ÷ 2 = 0.06160 m. In mm: 0.06160 × 10³ = 61.6. Mark scheme (2 marks). C1: d = vt/2. A1: d = 61.6 mm.', 2, NULL, NULL),
('d7bc1dfd-aeda-5491-8726-d3947cc5fa2d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 8, 8, 'Why is the time for an echo halved when finding the depth of a boundary?', NULL, 1, 'multiple_choice'::answer_type, 'The pulse travels to the boundary and back again', NULL, false, NULL, false, NULL, 'The total path is twice the depth. Mark scheme (1 mark). B1: C (The pulse travels to the boundary and back again).', 1, NULL, NULL),
('5833f62c-9212-530c-8e15-900f385f9f83', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 9, 9, 'A ship''s sonar pulse returns from the sea bed after 0.40 s. Sound travels at 1500 m s⁻¹ in sea water. Calculate the depth of the sea.', NULL, 1, 'numeric'::answer_type, '300', 'm', false, NULL, false, NULL, 'd = vt/2 = 1500 × 0.40 ÷ 2 = 300 m. Mark scheme (2 marks). C1: d = vt/2. A1: d = 300 m.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 250" role="img" aria-labelledby="fg0cd76064-t fg0cd76064-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0cd76064-t">Echo sounding</title><desc id="fg0cd76064-d">A ship sends a sonar pulse straight down to the sea bed; the echo returns 0.40 s later.</desc><line x1="20" y1="60" x2="400" y2="60" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,58 270,58 255,74 165,74" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="195" y="38" width="30" height="20" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="200" y1="76" x2="200" y2="211.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,216 197,209.7 203,209.7" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="220" y1="216" x2="220" y2="80.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="220,76 223,82.3 217,82.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><path d="M20,220 Q120,210 210,220 T400,224" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="390" y="238" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">sea bed</text><text x="240" y="140" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">echo after 0.40 s</text></svg>', 'A ship sends a sonar pulse straight down to the sea bed; the echo returns 0.40 s later.'),
('f3390be2-8669-5cc0-bd4e-52bf1eaf8078', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 10, 10, 'What does an A-scan display?', NULL, 1, 'multiple_choice'::answer_type, 'The strength of the echoes against time, as peaks on a trace', NULL, false, NULL, false, NULL, 'Peak positions give the depths of boundaries along one line. Mark scheme (1 mark). B1: A (The strength of the echoes against time, as peaks on a trace).', 1, NULL, NULL),
('12164723-0c1a-561c-a0c5-2d6705807786', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 11, 11, 'A boundary is 45 mm deep in tissue where v = 1500 m s⁻¹. Calculate the time for its echo to return, in µs.', NULL, 1, 'numeric'::answer_type, '60 us', 'µs', false, NULL, false, NULL, 't = 2d/v = 2 × 0.045 ÷ 1500 = 6.0 × 10⁻⁵ s. In µs: 6.0 × 10⁻⁵ × 10⁶ = 60. Mark scheme (2 marks). C1: t = 2d/v. A1: t = 60 µs.', 2, NULL, NULL),
('9b43e2ba-8726-5b8b-aac7-de99899d9032', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 12, 12, 'Why is ultrasound sent as short pulses rather than continuously for echo sounding?', NULL, 1, 'multiple_choice'::answer_type, 'So that each echo can be timed before the next pulse is sent', NULL, false, NULL, false, NULL, 'The time from emission to echo gives the depth. Mark scheme (1 mark). B1: D (So that each echo can be timed before the next pulse is sent).', 1, NULL, NULL),
('3e312c89-eb58-5196-a842-5ad5d5335a26', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 13, 13, 'A bat emits a click and hears the echo from a wall 0.020 s later. Sound travels at 340 m s⁻¹ in air. How far away is the wall?', NULL, 1, 'numeric'::answer_type, '3.4', 'm', false, NULL, false, NULL, 'd = 340 × 0.020 ÷ 2 = 3.4 m. Mark scheme (2 marks). C1: d = vt/2. A1: d = 3.4 m.', 2, NULL, NULL),
('77f8f115-8c39-5c41-8dc4-35015c6833e5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 14, 14, 'What does the height of a peak on an A-scan indicate?', NULL, 1, 'multiple_choice'::answer_type, 'The strength of the echo from that boundary', NULL, false, NULL, false, NULL, 'Depth comes from the time; height from the amount reflected and attenuation. Mark scheme (1 mark). B1: B (The strength of the echo from that boundary).', 1, NULL, NULL),
('adc64f49-2ddd-544e-96a4-f3c1faf3fb73', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 15, 15, 'On an A-scan, an echo appears 0.12 ms after the transmitted pulse. If v = 1540 m s⁻¹, calculate the depth of the boundary in cm.', NULL, 1, 'numeric'::answer_type, '9.24 cm', 'cm', false, NULL, false, NULL, 'd = 1540 × 0.12 × 10⁻³ ÷ 2 = 0.09240 m. In cm: 0.09240 × 100 = 9.24. Mark scheme (2 marks). C1: d = vt/2. A1: d = 9.24 cm.', 2, NULL, NULL),
('9338e7f1-d2f0-5c25-86c4-c7e9ad74bcde', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 16, 16, 'Which quantity must be known to convert echo times into depths?', NULL, 1, 'multiple_choice'::answer_type, 'The speed of ultrasound in the tissue', NULL, false, NULL, false, NULL, 'The depth is d = vt/2, so the speed v in the tissue is needed. Mark scheme (1 mark). B1: C (The speed of ultrasound in the tissue).', 1, NULL, NULL),
('c8ca6c79-ba34-546c-aa8a-f5e5af030488', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 17, 17, 'A fishing boat''s echo sounder detects a shoal of fish 60 m below. Taking the speed of sound in water as 1500 m s⁻¹, calculate the echo time.', NULL, 1, 'numeric'::answer_type, '0.08', 's', false, NULL, false, NULL, 't = 2d/v = 2 × 60 ÷ 1500 = 0.080 s. Mark scheme (2 marks). C1: t = 2d/v. A1: t = 0.080 s.', 2, NULL, NULL),
('01cfa4e0-885c-582a-95d7-6434934ecb5e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 18, 18, 'Two echoes from one pulse arrive at different times. What does the later echo show?', NULL, 1, 'multiple_choice'::answer_type, 'A boundary deeper below the probe', NULL, false, NULL, false, NULL, 'Larger echo time means larger depth. Mark scheme (1 mark). B1: A (A boundary deeper below the probe).', 1, NULL, NULL),
('8acc85e9-ddd1-5c24-acc6-7fa252d68fdc', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 19, 19, 'Ultrasound of frequency 40 kHz is used by a parking sensor; sound travels at 340 m s⁻¹. Calculate its wavelength in mm.', NULL, 1, 'numeric'::answer_type, '8.5 mm', 'mm', false, NULL, false, NULL, 'λ = 340 ÷ 40 × 10³ = 8.5 × 10⁻³ m. In mm: 8.5 × 10⁻³ × 10³ = 8.5. Mark scheme (2 marks). C1: λ = v/f. A1: λ = 8.5 mm.', 2, NULL, NULL),
('2d01620e-93ab-5a1a-a581-474916066bde', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 20, 20, 'Why must the pulse repetition rate of an echo sounder not be too high?', NULL, 1, 'multiple_choice'::answer_type, 'Each echo must return before the next pulse is sent, or the echoes become confused', NULL, false, NULL, false, NULL, 'Deep targets need more time between pulses. Mark scheme (1 mark). B1: D (Each echo must return before the next pulse is sent, or the echoes become confused).', 1, NULL, NULL),
('8f87ba26-33d7-51ff-a425-4ca44b6c8b9f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'd8943c26-698b-4e81-97d1-7588165e9880', 'a-level', '30.6', '9702 coursebook 30.6 · Echo sounding', 21, 21, 'The time base of an A-scan display is 20 µs per division. An echo is 3.5 divisions after the transmitted pulse. Calculate the echo time in µs.', NULL, 1, 'numeric'::answer_type, '70 us', 'µs', false, NULL, false, NULL, 't = 3.5 × 20 = 70 µs. Mark scheme (2 marks). C1: divisions × time base. A1: t = 70 µs.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 240" role="img" aria-labelledby="fga026b366-t fga026b366-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga026b366-t">A-scan trace</title><desc id="fga026b366-d">A-scan trace with a time base of 20 µs per division: the transmitted pulse at 0 and an echo 3.5 divisions later.</desc><line x1="33" y1="34" x2="33" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="94.5" y1="34" x2="94.5" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="156" y1="34" x2="156" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217.5" y1="34" x2="217.5" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="279" y1="34" x2="279" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="340.5" y1="34" x2="340.5" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="402" y1="34" x2="402" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:roun