('bbd1eb30-204e-5e4b-9588-ac1a34bfbdcf', '77f8f115-8c39-5c41-8dc4-35015c6833e5', 'The speed of sound in that tissue', 'D', false, 3),
('f7f61962-3407-5fc5-8fdf-99652e826ba7', '9338e7f1-d2f0-5c25-86c4-c7e9ad74bcde', 'The frequency of the ultrasound', 'A', false, 0),
