('c4381941-bcf6-5dab-b5a9-076371e2b964', '2d01620e-93ab-5a1a-a581-474916066bde', 'The frequency would change', 'B', false, 1),
('1262b95b-826a-5e9f-8605-bddcab364b75', '2d01620e-93ab-5a1a-a581-474916066bde', 'The speed of sound would fall', 'C', false, 2),
('5fd49d3b-a3c3-5a04-b25c-39b6f888f583', '2d01620e-93ab-5a1a-a581-474916066bde', 'Each echo must return before the next pulse is sent, or the echoes become confused', 'D', true, 3),
('6f1115b9-e923-5be8-8f87-4a2565a4e8b6', 'cdaaafdf-1824-5bd2-98dd-60003beff94d', 'The calculated depth is larger than the real depth', 'A', false, 0),
('177c0458-d46a-5107-a60b-9fc9bc0b5e93', 'cdaaafdf-1824-5bd2-98dd-60003beff94d', 'The calculated depth is smaller than the real depth', 'B', true, 1),
('ed56b6ab-089b-552f-994a-690d4f966898', 'cdaaafdf-1824-5bd2-98dd-60003beff94d', 'The depth is unaffected', 'C', false, 2),
('c0867857-9c77-522f-b07c-36608ff8e350', 'cdaaafdf-1824-5bd2-98dd-60003beff94d', 'The echo disappears', 'D', false, 3),
