('583a6277-c983-5f7d-b7d0-5c94572cdba4', '468ab597-f119-5c19-8e6c-a161dd67eb4c', 'Ultrasound cannot reach the chest', 'B', false, 1),
('2abc45a3-42b8-53d1-ba18-fa47a28ab887', '468ab597-f119-5c19-8e6c-a161dd67eb4c', 'Air in the lungs reflects almost all the ultrasound at the tissue boundary', 'C', true, 2),
('6817942f-cfe9-5680-99bb-fce9f95ca8ab', '468ab597-f119-5c19-8e6c-a161dd67eb4c', 'The lungs move too slowly', 'D', false, 3),
('6291ec8e-2773-5a67-afce-f47c375fb033', '85cd25cc-d76b-511e-bce6-27cd5deeaf91', 'The ultrasound is attenuated on its longer path there and back', 'A', true, 0),
('c61a53ed-21f1-506c-8235-9f8685d55592', '85cd25cc-d76b-511e-bce6-27cd5deeaf91', 'Deep boundaries reflect a smaller fraction', 'B', false, 1),
('651b3bac-500c-58c6-9384-db7b954068b8', '85cd25cc-d76b-511e-bce6-27cd5deeaf91', 'The speed of sound is lower deep in the body', 'C', false, 2),
('694f7db4-5c53-54f8-8024-625c77126f22', '85cd25cc-d76b-511e-bce6-27cd5deeaf91', 'The frequency changes with depth', 'D', false, 3),
('5bf3aa50-66cb-5b25-8e82-39e4bd23d7ea', '15f16ba7-ef22-5271-bb04-d2acfe261a70', 'the deepest echo', 'A', false, 0),
('f3278700-c060-5453-a7a3-e6c74103618e', '15f16ba7-ef22-5271-bb04-d2acfe261a70', 'background noise only', 'B', false, 1),
('896152ae-a04e-5792-87ff-9765c85f293b', '15f16ba7-ef22-5271-bb04-d2acfe261a70', 'the echo from bone', 'C', false, 2),
('8433cc33-5950-52d8-b88f-3f2b72d4c16d', '15f16ba7-ef22-5271-bb04-d2acfe261a70', 'the transmitted pulse itself (and the echo from the skin surface)', 'D', true, 3),
('576740bb-69d2-57bf-adda-621918fe9476', '74218419-895c-5ab8-bb3e-f1b886039c8e', 'To make deep echoes appear earlier', 'A', false, 0),
('eb171ac2-123a-5bdc-8077-347baff4a1f3', '74218419-895c-5ab8-bb3e-f1b886039c8e', 'To make up for the extra attenuation suffered by echoes from deeper boundaries', 'B', true, 1),
('f347ca80-81a6-5af8-8637-8c5d3ba63898', '74218419-895c-5ab8-bb3e-f1b886039c8e', 'To raise the ultrasound frequency', 'C', false, 2),
('1ea10ccf-0311-5107-af47-26f29d4fa574', '74218419-895c-5ab8-bb3e-f1b886039c8e', 'To remove the transmitted pulse', 'D', false, 3),
('c2b4a6c1-d99a-51a8-b181-72c1ee678e87', '22715651-ead4-5a80-9c5d-0504f2838d2d', 'Lower frequencies give finer detail', 'A', false, 0),
('dcca3f30-7a49-593b-a97d-15e750e0b947', '22715651-ead4-5a80-9c5d-0504f2838d2d', 'Water cannot carry high frequencies at all', 'B', false, 1),
('efe7c63f-150c-5a87-beae-2813c35bee84', '22715651-ead4-5a80-9c5d-0504f2838d2d', 'Lower frequencies are attenuated less, so they travel the much greater distances needed', 'C', true, 2),
('f922acbc-64db-52bc-99fc-4e0a2f83b2dc', '22715651-ead4-5a80-9c5d-0504f2838d2d', 'Lower frequencies travel faster', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('d0e1960a-da6c-5885-ad96-48b32cd77257', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 7, 7, 'Liver tissue has a density of 1060 kg m⁻³ and ultrasound travels through it at 1550 m s⁻¹. Calculate its acoustic impedance in units of 10⁶ kg m⁻² s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.643', '10⁶ kg m⁻² s⁻¹', false, NULL, false, NULL, 'Z = ρc = 1060 × 1550 = 1.64 × 10⁶ kg m⁻² s⁻¹. Mark scheme (2 marks). C1: Z = ρc. A1: Z = 1.64 × 10⁶ kg m⁻² s⁻¹.', 2, NULL, NULL),
('596f5bb9-bd3e-5c39-80f9-03316d278410', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 8, 8, 'How is a B-scan image formed?', NULL, 1, 'multiple_choice'::answer_type, 'Echoes from many lines through the body are combined into a two-dimensional picture of a slice', NULL, false, NULL, false, NULL, 'An array of transducers sends pulses along many directions. Mark scheme (1 mark). B1: C (Echoes from many lines through the body are combined into a two-dimensional picture of a slice).', 1, NULL, NULL),
('3c50f133-b6f3-52b3-a4a7-f08b7f2d7225', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 9, 9, 'Calculate the intensity reflection coefficient at a soft tissue–bone boundary, given Z = 1.63 × 10⁶ kg m⁻² s⁻¹ for tissue and 7.80 × 10⁶ kg m⁻² s⁻¹ for bone.', NULL, 1, 'numeric'::answer_type, '0.4281', NULL, false, NULL, false, NULL, 'α = (7.80 − 1.63)² ÷ (7.80 + 1.63)² = 0.428. Mark scheme (2 marks). C1: α formula. A1: α = 0.428.', 2, NULL, NULL),
('12143fc5-722c-54db-a1b9-18a4ba5e2eef', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 10, 10, 'On a B-scan display, what does the brightness of each dot show?', NULL, 1, 'multiple_choice'::answer_type, 'The strength of the echo from that point', NULL, false, NULL, false, NULL, 'Bright dots mark strongly reflecting boundaries. Mark scheme (1 mark). B1: A (The strength of the echo from that point).', 1, NULL, NULL),
('df0c56ab-2065-5435-ae5d-659e2b76b6d2', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 11, 11, 'An echo returns 52 µs after a pulse is sent into tissue where v = 1540 m s⁻¹. How deep is the reflecting boundary, in mm?', NULL, 1, 'numeric'::answer_type, '40.04 mm', 'mm', false, NULL, false, NULL, 'd = 1540 × 52 × 10⁻⁶ ÷ 2 = 0.04004 m. In mm: 0.04004 × 10³ = 40.0. Mark scheme (2 marks). C1: d = vt/2. A1: d = 40.0 mm.', 2, NULL, NULL),
('1bad0bdb-37c7-5f0d-8f47-ebfe42f7c9e4', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 12, 12, 'Which part of the body is hardest to image with ultrasound?', NULL, 1, 'multiple_choice'::answer_type, 'The inside of the lungs', NULL, false, NULL, false, NULL, 'Air reflects almost all the ultrasound. Mark scheme (1 mark). B1: D (The inside of the lungs).', 1, NULL, NULL),
('e57c0ced-6fe3-51a4-9c01-1f2f32aaf061', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 13, 13, 'A 7.5 MHz probe is used on tissue where v = 1540 m s⁻¹. Calculate the wavelength in mm.', NULL, 1, 'numeric'::answer_type, '0.2053 mm', 'mm', false, NULL, false, NULL, 'λ = 1540 ÷ 7.5 × 10⁶ = 2.053 × 10⁻⁴ m. In mm: 2.053 × 10⁻⁴ × 10³ = 0.205. Mark scheme (2 marks). C1: λ = v/f. A1: λ = 0.205 mm.', 2, NULL, NULL),
('d1aafd8b-79f3-5d6a-9d39-841b4299d2e9', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 14, 14, 'What does a B-scan probe usually contain?', NULL, 1, 'multiple_choice'::answer_type, 'A row (array) of many small piezoelectric crystals', NULL, false, NULL, false, NULL, 'The array sends and receives along many lines. Mark scheme (1 mark). B1: B (A row (array) of many small piezoelectric crystals).', 1, NULL, NULL),
('c7b408fe-e1ab-5470-b95a-57efeee5f049', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 15, 15, 'At a boundary the intensity reflection coefficient is 0.012. What fraction of the incident intensity is transmitted?', NULL, 1, 'numeric'::answer_type, '0.988', NULL, false, NULL, false, NULL, 'Transmitted = 1 − 0.012 = 0.988. Mark scheme (2 marks). C1: 1 − α. A1: fraction = 0.988.', 2, NULL, NULL),
('e6dd4fcb-2a72-5d58-aae1-761bd6a6de67', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 16, 16, 'What does medical ultrasound imaging detect?', NULL, 1, 'multiple_choice'::answer_type, 'Echoes from boundaries between tissues', NULL, false, NULL, false, NULL, 'Each boundary reflects part of the pulse. Mark scheme (1 mark). B1: C (Echoes from boundaries between tissues).', 1, NULL, NULL),
('a81776a5-997b-5d0d-a515-8cf5ba33e136', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 17, 17, 'A boundary is 9.0 cm deep in tissue where v = 1500 m s⁻¹. How long after the pulse does its echo return, in µs?', NULL, 1, 'numeric'::answer_type, '120 us', 'µs', false, NULL, false, NULL, 't = 2 × 0.090 ÷ 1500 = 1.2 × 10⁻⁴ s. In µs: 1.2 × 10⁻⁴ × 10⁶ = 120. Mark scheme (2 marks). C1: t = 2d/v. A1: t = 120 µs.', 2, NULL, NULL),
('65df5a9d-7e21-5fce-bd87-ff290dab97f9', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 18, 18, 'Why does a B-scanner send many pulses every second?', NULL, 1, 'multiple_choice'::answer_type, 'To build up and refresh the image so that moving organs can be watched', NULL, false, NULL, false, NULL, 'Real-time imaging needs many frames per second. Mark scheme (1 mark). B1: A (To build up and refresh the image so that moving organs can be watched).', 1, NULL, NULL),
('c4fe1532-305d-5bf4-af7b-02067d4860b5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 19, 19, 'Calculate (acoustic impedance of bone, 7.80 × 10⁶) ÷ (acoustic impedance of soft tissue, 1.63 × 10⁶), both in kg m⁻² s⁻¹.', NULL, 1, 'numeric'::answer_type, '4.785', NULL, false, NULL, false, NULL, 'Ratio = 7.80 ÷ 1.63 = 4.79. Mark scheme (2 marks). C1: ratio. A1: ratio = 4.79.', 2, NULL, NULL),
('f607e145-af84-528a-b99b-bf47d818629f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 20, 20, 'Why do structures behind bone often appear dark on an ultrasound image?', NULL, 1, 'multiple_choice'::answer_type, 'Most of the ultrasound is reflected or absorbed at the bone, so little reaches them', NULL, false, NULL, false, NULL, 'This is called acoustic shadowing. Mark scheme (1 mark). B1: D (Most of the ultrasound is reflected or absorbed at the bone, so little reaches them).', 1, NULL, NULL),
('41ef7f9e-675a-5697-8cfd-c8a7141276fb', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 21, 21, 'A scanner shows 30 frames per second, each made of 128 scan lines. How many scan lines are produced per second?', NULL, 1, 'numeric'::answer_type, '3840', NULL, false, NULL, false, NULL, 'Lines = 30 × 128 = 3840. Mark scheme (2 marks). C1: frames × lines. A1: lines = 3840.', 2, NULL, NULL),
('e77060d9-8382-5506-aa27-cc00689b0e42', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 22, 22, 'A higher ultrasound frequency is chosen. What is gained and what is lost?', NULL, 1, 'multiple_choice'::answer_type, 'Better resolution is gained; penetration depth is lost', NULL, false, NULL, false, NULL, 'Shorter λ resolves more detail but is attenuated more. Mark scheme (1 mark). B1: B (Better resolution is gained; penetration depth is lost).', 1, NULL, NULL),
('df3ea87c-39df-594f-adb8-a6c7514cc894', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 23, 23, 'For blood, ρ = 1060 kg m⁻³ and the speed of sound is 1570 m s⁻¹. What is Z for blood, in units of 10⁶ kg m⁻² s⁻¹?', NULL, 1, 'numeric'::answer_type, '1.664', '10⁶ kg m⁻² s⁻¹', false, NULL, false, NULL, 'Z = 1060 × 1570 = 1.66 × 10⁶ kg m⁻² s⁻¹. Mark scheme (1 mark). A1: Z = 1.66 × 10⁶ kg m⁻² s⁻¹.', 1, NULL, NULL),
('b232f795-a818-5bd1-8ffe-15e83d637724', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 24, 24, 'An echo returns from the back wall of a bladder 104 µs after the pulse. Taking v = 1540 m s⁻¹, how deep is the wall, in cm?', NULL, 1, 'numeric'::answer_type, '8.008 cm', 'cm', false, NULL, false, NULL, 'd = 1540 × 104 × 10⁻⁶ ÷ 2 = 0.08008 m. In cm: 0.08008 × 100 = 8.01. Mark scheme (2 marks). C1: d = vt/2. A1: d = 8.01 cm.', 2, NULL, NULL),
('bc67aa86-b839-5944-905c-73ad7f3ff7e7', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 25, 25, 'Calculate the percentage of the intensity reflected at a fat–muscle boundary (Z = 1.38 × 10⁶ and 1.70 × 10⁶ kg m⁻² s⁻¹).', NULL, 2, 'numeric'::answer_type, '1.079', '%', false, NULL, false, NULL, 'α = (1.70 − 1.38)² ÷ (1.70 + 1.38)² = 0.01079. Percentage = 0.01079 × 100 = 1.08 %. Mark scheme (3 marks). C1: α. C1: × 100. A1: percentage = 1.08%.', 3, NULL, NULL),
('cd417cf2-c096-5628-a1b9-0e40866ee3d6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 26, 26, 'Ultrasound crosses a gel–skin boundary (α = 0.0039) and then a fat–muscle boundary (α = 0.011). What fraction of the incident intensity passes through both?', NULL, 2, 'numeric'::answer_type, '0.9851', NULL, false, NULL, false, NULL, 'Fraction = (1 − 0.0039) × (1 − 0.011) = 0.985. Mark scheme (3 marks). C1: transmitted at each. C1: multiply. A1: fraction = 0.985.', 3, NULL, NULL),
('0140a490-9792-5afa-9a3c-a4560e216dff', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 27, 27, 'Each scan line of a B-scan must wait for echoes from 15 cm deep (v = 1540 m s⁻¹), and each frame has 128 lines. Calculate the greatest possible frame rate.', NULL, 2, 'numeric'::answer_type, '40.1', 'Hz', false, NULL, false, NULL, 'Time per line = 2 × 0.15 ÷ 1540 = 1.948 × 10⁻⁴ s. Frame time = 128 × 1.948 × 10⁻⁴ = 0.02494 s. Frame rate = 1 ÷ 0.02494 = 40.1 Hz. Mark scheme (4 marks). C1: time per line. C1: frame time. C1: frame rate. A1: f = 40.1 Hz.', 4, NULL, NULL),
('5ec95562-bcf2-5939-a056-a15f55fa46ac', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 28, 28, 'A B-scan of the abdomen shows a dark band behind a gallstone. What causes it?', NULL, 2, 'multiple_choice'::answer_type, 'The stone reflects and absorbs most of the ultrasound, so little reaches the tissue behind it', NULL, false, NULL, false, NULL, 'Acoustic shadowing behind strongly reflecting objects. Mark scheme (3 marks). C1: strong reflection/absorption. C1: little energy beyond. A1: C (The stone reflects and absorbs most of the ultrasound, so little reaches the tissue behind it).', 3, NULL, NULL),
('5ae95b52-e13c-5b4f-ac0d-a6dcbfbf791f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 29, 29, 'An echo from the far side of a fetal head returns 120 µs after the echo from the near side. The speed of ultrasound in the head is 1540 m s⁻¹. Calculate the width of the head in mm.', NULL, 2, 'numeric'::answer_type, '92.4 mm', 'mm', false, NULL, false, NULL, 'w = 1540 × 120 × 10⁻⁶ ÷ 2 = 0.09240 m. In mm: 0.09240 × 10³ = 92.4. Mark scheme (3 marks). C1: d = vΔt/2. C1: value. A1: w = 92.4 mm.', 3, NULL, NULL),
('341f1ba5-4cae-5092-8ca9-367b821b0143', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 30, 30, 'A matching layer between a crystal (Z = 30 × 10⁶ kg m⁻² s⁻¹) and skin (Z = 1.7 × 10⁶ kg m⁻² s⁻¹) works best with Z = √(Z₁Z₂). Calculate this value in units of 10⁶ kg m⁻² s⁻¹.', NULL, 2, 'numeric'::answer_type, '7.141', '10⁶ kg m⁻² s⁻¹', false, NULL, false, NULL, 'Z = √(30 × 10⁶ × 1.7 × 10⁶) = 7.14 × 10⁶ kg m⁻² s⁻¹. Mark scheme (3 marks). C1: geometric mean. C1: value. A1: Z = 7.14 × 10⁶ kg m⁻² s⁻¹.', 3, NULL, NULL),
('70e2f575-380f-5743-8f1e-c264f37c0a18', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 31, 31, 'How is a B-scan different from an A-scan?', NULL, 2, 'multiple_choice'::answer_type, 'A B-scan shows a 2-D image built from many lines; an A-scan shows echo strength against time along one line', NULL, false, NULL, false, NULL, 'B stands for brightness: echoes appear as bright dots. Mark scheme (3 marks). C1: A-scan one line. C1: B-scan 2-D image. A1: A (A B-scan shows a 2-D image built from many lines; an A-scan shows echo strength against time along one line).', 3, NULL, NULL),
('97a4edcc-86ea-5e3e-b1ba-1cebb1f785bb', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 32, 32, 'An ultrasound beam loses intensity by a factor of 100 between the probe and a boundary. Express this loss in decibels, using 10 lg(I₀/I).', NULL, 2, 'numeric'::answer_type, '20', 'dB', false, NULL, false, NULL, 'Loss = 10 × lg 100 = 20 dB. Mark scheme (3 marks). C1: 10 lg ratio. C1: value. A1: loss = 20 dB.', 3, NULL, NULL),
('8d4e1a03-1922-5cf8-88e7-a6e332980b58', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 33, 33, 'A beam is attenuated by 1.0 dB per cm. What fraction of its intensity remains after 3.0 cm?', NULL, 2, 'numeric'::answer_type, '0.5012', NULL, false, NULL, false, NULL, 'Loss = 3.0 dB, so I/I₀ = 10^(−3.0 ÷ 10) = 10^(−0.30) = 0.501. Mark scheme (3 marks). C1: total dB. C1: convert to ratio. A1: fraction = 0.501.', 3, NULL, NULL),
('73b9ba86-d725-5302-90bf-abea9a65b931', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 34, 34, 'Why can ultrasound show heart valves moving but a CT scan cannot easily do so?', NULL, 2, 'multiple_choice'::answer_type, 'Ultrasound images are produced in real time at many frames per second', NULL, false, NULL, false, NULL, 'Fast frame rates follow motion. Mark scheme (3 marks). C1: real time. C1: high frame rate. A1: D (Ultrasound images are produced in real time at many frames per second).', 3, NULL, NULL),
('d93d5e1a-ac1b-52b0-97f9-387941f94e22', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 35, 35, 'A tissue has an acoustic impedance of 1.65 × 10⁶ kg m⁻² s⁻¹ and a density of 1050 kg m⁻³. Calculate the speed of ultrasound in it.', NULL, 2, 'numeric'::answer_type, '1571', 'm s⁻¹', false, NULL, false, NULL, 'c = Z/ρ = 1.65 × 10⁶ ÷ 1050 = 1570 m s⁻¹. Mark scheme (3 marks). C1: c = Z/ρ. C1: value. A1: c = 1570 m s⁻¹.', 3, NULL, NULL),
('7effa8a2-697f-5e22-8d05-9fedcb75977b', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 36, 36, 'A boundary 5.0 cm deep reflects 0.90% of the intensity. The tissue has an intensity attenuation coefficient of 0.23 cm⁻¹. What fraction of the transmitted intensity returns to the probe?', NULL, 2, 'numeric'::answer_type, '9.023e-4', NULL, false, NULL, false, NULL, 'Path = 2 × 5.0 = 10 cm. Fraction = 0.0090 × e^(−0.23 × 10) = 9.02 × 10⁻⁴. Mark scheme (4 marks). M1: round trip. C1: attenuation. C1: × reflection. A1: fraction = 9.02 × 10⁻⁴.', 4, NULL, NULL),
('b445fbbb-d98b-5b8b-a39f-d76ad924044e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 37, 37, 'Which boundary produces the strongest echo?', NULL, 2, 'multiple_choice'::answer_type, 'Soft tissue to air', NULL, false, NULL, false, NULL, 'The impedance mismatch is largest. Mark scheme (3 marks). C1: largest ΔZ. C1: α ≈ 1. A1: B (Soft tissue to air).', 3, NULL, NULL),
('b8ab5098-b97d-51cc-86b2-e91e2401790a', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 38, 38, 'The smallest detail resolvable is about one wavelength. Estimate it for 5.0 MHz ultrasound in tissue (v = 1540 m s⁻¹), in mm.', NULL, 2, 'numeric'::answer_type, '0.308 mm', 'mm', false, NULL, false, NULL, 'λ = 1540 ÷ 5.0 × 10⁶ = 3.080 × 10⁻⁴ m. In mm: 3.080 × 10⁻⁴ × 10³ = 0.308. Mark scheme (3 marks). C1: λ = v/f. C1: value. A1: λ = 0.308 mm.', 3, NULL, NULL),
('4ddfdb55-a64c-516f-af2f-63561971e03a', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 39, 39, 'A structure is 2.5 cm thick. Calculate the time between the echoes from its front and back surfaces (v = 1540 m s⁻¹), in µs.', NULL, 2, 'numeric'::answer_type, '32.47 us', 'µs', false, NULL, false, NULL, 'Δt = 2 × 0.025 ÷ 1540 = 3.247 × 10⁻⁵ s. In µs: 3.247 × 10⁻⁵ × 10⁶ = 32.5. Mark scheme (3 marks). C1: Δt = 2d/v. C1: s to µs. A1: Δt = 32.5 µs.', 3, NULL, NULL),
('0744c515-53ad-5e95-9a30-c1edc88bfef8', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 40, 40, 'Give the main advantage of ultrasound over CT for a routine scan of a pregnant woman.', NULL, 2, 'multiple_choice'::answer_type, 'It uses no ionising radiation', NULL, false, NULL, false, NULL, 'Ionising radiation could harm the fetus. Mark scheme (3 marks). C1: non-ionising. C1: safe for fetus. A1: C (It uses no ionising radiation).', 3, NULL, NULL),
('d1c5f4f4-6bc0-53c3-a36b-bdc27f913681', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 41, 41, 'Calculate the intensity reflection coefficient at the gel–skin boundary, taking Z(gel) = 1.50 × 10⁶ and Z(skin) = 1.70 × 10⁶ kg m⁻² s⁻¹.', NULL, 2, 'numeric'::answer_type, '0.003906', NULL, false, NULL, false, NULL, 'α = (1.70 − 1.50)² ÷ (1.70 + 1.50)² = 0.00391. Mark scheme (3 marks). C1: formula. C1: value. A1: α = 0.00391.', 3, NULL, NULL),
('db87e1d8-f048-5fd2-bb6d-ec2575688dec', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 42, 42, 'A scanner builds each frame from 200 lines and shows 25 frames per second. How many pulses per second must it send?', NULL, 2, 'numeric'::answer_type, '5000', NULL, false, NULL, false, NULL, 'Pulses = 200 × 25 = 5000. Mark scheme (3 marks). C1: lines × frames. C1: value. A1: pulses = 5000.', 3, NULL, NULL),
('ccd07c29-9625-5396-9124-066c91c2dc89', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 43, 43, 'A cardiac scanner must image to a depth of 20 cm (v = 1540 m s⁻¹) with 96 lines per frame. (a) Calculate the time for one line. (b) Calculate the time for one frame. (c) Calculate the greatest frame rate.', NULL, 3, 'numeric'::answer_type, '40.1', 'Hz', false, NULL, false, NULL, '(a) 2 × 0.20 ÷ 1540 = 2.597 × 10⁻⁴ s. (b) 96 × 2.597 × 10⁻⁴ = 0.02494 s. (c) 1 ÷ 0.02494 = 40.1 Hz. Mark scheme (5 marks). C1: line time. C1: frame time. M1: rate = 1/time. C1: value. A1: f = 40.1 Hz.', 5, NULL, NULL),
('51556f7e-0a9f-59f3-b831-013a0a349664', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 44, 44, 'Ultrasound passes from fat (Z = 1.38 × 10⁶) into muscle (Z = 1.70 × 10⁶), then reflects at a muscle–bone boundary (Z = 7.80 × 10⁶, units kg m⁻² s⁻¹) and returns into the fat. Ignore attenuation. (a) Calculate the reflection coefficient at the fat–muscle boundary. (b) Calculate it at the muscle–bone boundary. (c) Calculate the fraction of the incident intensity that returns into the fat from the bone. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.4034', NULL, false, NULL, false, NULL, '(a) 0.01079. (b) ((7.80 − 1.70) ÷ (7.80 + 1.70))² = 0.4123. (c) (1 − 0.01079)² × 0.4123 = 0.403. Mark scheme (6 marks). C1: first α. C1: second α. M1: transmit twice, reflect once. C1: substitution. C1: value. A1: fraction = 0.403.', 6, NULL, NULL),
('c919fd9a-cc89-52ee-90c0-b4363bb829f1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 45, 45, 'A matching layer works best if its thickness is a quarter of the wavelength in it. Ultrasound of 5.0 MHz travels at 3000 m s⁻¹ in the layer. (a) Calculate the wavelength in the layer. (b) Calculate the ideal thickness, in mm.', NULL, 3, 'numeric'::answer_type, '0.15 mm', 'mm', false, NULL, false, NULL, '(a) λ = 3000 ÷ 5.0 × 10⁶ = 6.0 × 10⁻⁴ m. (b) t = 6.0 × 10⁻⁴ ÷ 4 = 1.5 × 10⁻⁴ m, which in mm is 1.5 × 10⁻⁴ × 10³ = 0.15. Mark scheme (5 marks). C1: λ = v/f. M1: quarter wavelength. C1: value. C1: m to mm. A1: t = 0.15 mm.', 5, NULL, NULL),
('508390c5-7051-553a-94ca-79c3c15a902c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 46, 46, 'A tissue sample has a density of 1050 kg m⁻³; ultrasound pulses take 20.0 µs to cross 1.60 cm of it and return. (a) Calculate the speed of ultrasound. (b) Calculate its acoustic impedance. (c) Calculate the reflection coefficient where it meets a material of Z = 2.0 × 10⁶ kg m⁻² s⁻¹. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.007561', NULL, false, NULL, false, NULL, '(a) v = 2 × 0.016 ÷ 20.0 × 10⁻⁶ = 1600 m s⁻¹. (b) Z = 1050 × 1600 = 1.680 × 10⁶ kg m⁻² s⁻¹. (c) α = ((2.0 × 10⁶ − 1.680 × 10⁶) ÷ (2.0 × 10⁶ + 1.680 × 10⁶))² = 0.00756. Mark scheme (6 marks). C1: v = 2d/t. C1: Z = ρv. M1: α formula. C1: substitution. C1: value. A1: α = 0.00756.', 6, NULL, NULL),
('17ac6d53-10b3-593e-a26a-1febec7b7e25', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 47, 47, 'An abdominal probe operates at 3.5 MHz, and the tissue attenuates by 0.50 dB cm⁻¹ per MHz. (a) Calculate the attenuation per cm at this frequency. (b) Calculate the total attenuation for an echo from 8.0 cm deep. (c) Calculate the fraction of intensity remaining from attenuation alone. Give only the answer to (b), in dB.', NULL, 3, 'numeric'::answer_type, '28', 'dB', false, NULL, false, NULL, '(a) 0.50 × 3.5 = 1.75 dB cm⁻¹. (b) Round trip 16 cm: 1.75 × 16 = 28 dB. (c) 10^(−2.8) ≈ 1.6 × 10⁻³. Mark scheme (5 marks). C1: dB per cm. M1: round trip. C1: value. C1: fraction. A1: attenuation = 28 dB.', 5, NULL, NULL),
('a314fe97-613a-518e-92fe-35ecfe4bceb6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 48, 48, 'A B-scan uses 5.0 MHz ultrasound (v = 1540 m s⁻¹) and displays a 15 cm deep field on 500 pixel rows. (a) Calculate the depth represented by each pixel row in mm. (b) Calculate the wavelength in mm. (c) Explain which limits the depth detail more. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.3 mm', 'mm', false, NULL, false, NULL, '(a) 150 ÷ 500 = 0.30 mm. (b) λ = 1540 ÷ 5.0 × 10⁶ = 3.08 × 10⁻⁴ m, about 0.31 mm. (c) Both are similar, about 0.3 mm, so either can limit the detail. Mark scheme (6 marks). C1: field in mm. M1: ÷ rows. C1: value. C1: wavelength. B1: comparison. A1: depth per row = 0.30 mm.', 6, NULL, NULL),
('a0013eda-b623-5e7a-b835-d6f42ca86388', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '75e89d65-181a-4db5-a20b-511fa32bab7d', 'a-level', '30.7', '9702 coursebook 30.7 · Ultrasound scanning', 49, 49, 'An A-scan of an eye shows echoes at 6.5 µs (cornea), 9.0 µs (front of lens), 15.0 µs (back of lens) and 33.0 µs (retina). Use v = 1530 m s⁻¹ throughout. (a) Calculate the distance from the cornea to the retina. (b) Calculate the lens thickness. Give only the answer to (a), in mm.', NULL, 3, 'numeric'::answer_type, '20.27 mm', 'mm', false, NULL, false, NULL, '(a) d = 1530 × (33.0 − 6.5) × 10⁻⁶ ÷ 2 = 0.02027 m. In mm: 0.02027 × 10³ = 20.3. (b) 1530 × 6.0 × 10⁻⁶ ÷ 2 ≈ 4.6 mm. Mark scheme (5 marks). C1: time difference. M1: d = vt/2. C1: value. C1: lens. A1: d = 20.3 mm.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 240" role="img" aria-labelledby="fg5f36d846-t fg5f36d846-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5f36d846-t">A-scan of an eye</title><desc id="fg5f36d846-d">A-scan of an eye: the transmitted pulse at 0 and echoes at 6.5 µs (cornea), 9.0 µs (front of lens), 15.0 µs (back of lens) and 33.0 µs (retina).</desc><line x1="33" y1="34" x2="33" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125.3" y1="34" x2="125.3" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217.5" y1="34" x2="217.5" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="309.8" y1="34" x2="309.8" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="402" y1="34" x2="402" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-line