INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('63ef15e1-f1a6-5233-b9df-58003d03794b', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 9, 9, 'An annihilation photon has an energy of 8.2 × 10⁻¹⁴ J. Calculate its wavelength in units of 10⁻¹² m. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '2.426', '10⁻¹² m', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 8.2 × 10⁻¹⁴ = 2.43 × 10⁻¹² m. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 2.43 × 10⁻¹² m.', 2, NULL, NULL),
('3b09e757-9037-5b70-893d-98483d795d9d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 10, 10, 'What does the tracer used in PET scanning emit?', NULL, 1, 'multiple_choice'::answer_type, 'Positrons', NULL, false, NULL, false, NULL, 'Each positron annihilates with an electron nearby. Mark scheme (1 mark). B1: C (Positrons).', 1, NULL, NULL),
('9e723c54-f6df-5412-96e1-77c0b3cc612c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 11, 11, 'Fluorine-18 has a half-life of 110 minutes. A dose has an activity of 400 MBq. Calculate its activity 220 minutes later, in MBq.', NULL, 1, 'numeric'::answer_type, '100', 'MBq', false, NULL, false, ARRAY['1e8']::text[], '220 ÷ 110 = 2 half-lives: A = 400 × (1/2)² = 100 MBq. Mark scheme (2 marks). C1: two half-lives. A1: A = 100 MBq.', 2, NULL, NULL),
('df657b5b-01d9-5f59-a9fc-27319536f574', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 12, 12, 'What is produced when a positron meets an electron?', NULL, 1, 'multiple_choice'::answer_type, 'Two γ-ray photons travelling in opposite directions', NULL, false, NULL, false, NULL, 'Their mass becomes the energy of two photons. Mark scheme (1 mark). B1: A (Two γ-ray photons travelling in opposite directions).', 1, NULL, NULL),
('01295333-71b2-5ad7-8737-9ded8227aa63', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 13, 13, 'An annihilation photon has an energy of 0.511 MeV. Calculate its momentum in units of 10⁻²² kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '2.725', '10⁻²² kg m s⁻¹', false, NULL, false, NULL, 'E = 0.511 × 10⁶ × 1.60 × 10⁻¹⁹ = 8.176 × 10⁻¹⁴ J. p = E/c = 8.176 × 10⁻¹⁴ ÷ 3.00 × 10⁸ = 2.73 × 10⁻²² kg m s⁻¹. Mark scheme (2 marks). C1: p = E/c. A1: p = 2.73 × 10⁻²² kg m s⁻¹.', 2, NULL, NULL),
('566a2dd5-b9fe-5d74-8103-728aae944949', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 14, 14, 'What does a PET scanner detect?', NULL, 1, 'multiple_choice'::answer_type, 'Pairs of γ-ray photons arriving at opposite detectors at the same time', NULL, false, NULL, false, NULL, 'Coincidence detection identifies annihilations. Mark scheme (1 mark). B1: D (Pairs of γ-ray photons arriving at opposite detectors at the same time).', 1, NULL, NULL),
('a2af5e72-7d6d-5fb0-9177-bd382d78b445', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 15, 15, 'Calculate the time a γ-ray photon takes to cross a detector ring 0.80 m in diameter, in ns. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '2.667 ns', 'ns', false, NULL, false, NULL, 't = d/c = 0.80 ÷ 3.00 × 10⁸ = 2.667 × 10⁻⁹ s. In ns: 2.667 × 10⁻⁹ × 10⁹ = 2.67. Mark scheme (2 marks). C1: t = d/c. A1: t = 2.67 ns.', 2, NULL, NULL),
('bd715409-9111-5a47-a801-a77ac35c3a87', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 16, 16, 'Which tracer is most often used in PET?', NULL, 1, 'multiple_choice'::answer_type, 'A glucose compound labelled with fluorine-18', NULL, false, NULL, false, NULL, 'Active cells take up glucose, so the tracer collects there. Mark scheme (1 mark). B1: B (A glucose compound labelled with fluorine-18).', 1, NULL, NULL),
('d7eb0418-f467-53c1-a4ee-40be83e051e6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 17, 17, 'Fluorine-18 has a half-life of 110 minutes (6600 s). Calculate its decay constant in s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.05e-4', 's⁻¹', false, NULL, false, NULL, 'λ = 0.693 ÷ 6600 = 1.05 × 10⁻⁴ s⁻¹. Mark scheme (2 marks). C1: λ = ln 2/t½. A1: λ = 1.05 × 10⁻⁴ s⁻¹.', 2, NULL, NULL),
('29d8b848-562f-524c-b2e6-732fd0f34a18', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 18, 18, 'Where is the fluorine-18 for PET tracers usually produced?', NULL, 1, 'multiple_choice'::answer_type, 'In a cyclotron, often at or near the hospital', NULL, false, NULL, false, NULL, 'Its short half-life means it must be made close to where it is used. Mark scheme (1 mark). B1: C (In a cyclotron, often at or near the hospital).', 1, NULL, NULL),
('8ac3fa92-1361-5d01-bc1c-7a0053ad6264', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 19, 19, 'Calculate the frequency of a 0.511 MeV annihilation photon in units of 10²⁰ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.233', '10²⁰ Hz', false, NULL, false, NULL, 'f = E/h = 0.511 × 10⁶ × 1.60 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 1.23 × 10²⁰ Hz. Mark scheme (2 marks). C1: f = E/h. A1: f = 1.23 × 10²⁰ Hz.', 2, NULL, NULL),
('ded37060-7ee9-519f-844e-fdb90a27a389', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '36e936df-9896-57b6-a5e3-651ca3d785ed', 'a-level', '30.8', '9702 coursebook 30.8 · PET scanning', 20, 20, 'In PET, what is a "line of response"?', NULL, 1, 'multiple_choice'::answer_type, 'The line joining the two detectors that record a coincident pair of photons', NULL, false, NULL, false, NULL, 'The annihilation lies somewhere on this line. Mark scheme (1 mark). B1: A (The line joining the two detectors that record a coincident pair of photons).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fge6ab74d0-t fge6ab74d0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge6ab74d0-t">Line of response</title><desc id="fge6ab74d0-d">End-on view of a PET detector ring around a patient, with two photons from an annihilation travelling in opposite directions to two detectors.</desc><rect x="300" y="163" width="10" height="10" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="298.1" y="141.3" width="10" height="10" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="292.5" y="120.2" width="10" height="10" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="283.3" y="100.5" width="10" height="10" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="270.8" y="82.7" width="10" height="10" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="255.3" y="67.2" width="10" height="10" rx="0" styl